#### KPI Card
```typescript
// components/dashboard/kpi-card.tsx
'use client';

import { Card, Metric, Text, Flex, ProgressBar, Badge } from '@tremor/react';

interface KPICardProps {
  title: string;
  metric: string | number;
  metricFormat?: 'number' | 'currency' | 'percent';
  change?: number;
  changeType?: 'positive' | 'negative' | 'neutral';
  progress?: number;
  target?: string;
}

export function KPICard({
  title,
  metric,
  metricFormat = 'number',
  change,
  changeType = 'positive',
  progress,
  target,
}: KPICardProps) {
  const formatMetric = (value: string | number) => {
    if (typeof value === 'number') {
      switch (metricFormat) {
        case 'currency':
          return new Intl.NumberFormat('en-US', {
            style: 'currency',
            currency: 'USD',
            maximumFractionDigits: 0,
          }).format(value);
        case 'percent':
          return `${value.toFixed(1)}%`;
        default:
          return value.toLocaleString();
      }
    }
    return value;
  };

  return (
    <Card className="w-full">
      <Flex alignItems="start">
        <div>
          <Text>{title}</Text>
          <Metric>{formatMetric(metric)}</Metric>
        </div>
        {change !== undefined && (
          <Badge color={changeType === 'positive' ? 'emerald' : changeType === 'negative' ? 'rose' : 'gray'}>
            {change > 0 ? '+' : ''}{change}%
          </Badge>
        )}
      </Flex>
      {progress !== undefined && (
        <Flex className="mt-4">
          <Text>{progress}% of {target}</Text>
        </Flex>
      )}
      {progress !== undefined && (
        <ProgressBar value={progress} color="emerald" className="mt-2" />
      )}
    </Card>
  );
}
