### 4. Real-time WebSocket Integration

```typescript
// hooks/use-realtime-chart.ts
'use client';

import { useEffect, useState, useCallback, useRef } from 'react';

interface RealtimeChartOptions {
  maxPoints?: number;
  refreshInterval?: number;
  websocketUrl?: string;
}

interface DataPoint {
  timestamp: number;
  value: number;
  [key: string]: number;
}

export function useRealtimeChart<T extends DataPoint>({
  maxPoints = 60,
  refreshInterval = 1000,
  websocketUrl,
}: RealtimeChartOptions = {}) {
  const [data, setData] = useState<T[]>([]);
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<NodeJS.Timeout>();

  const addDataPoint = useCallback(
    (point: Omit<T, 'timestamp'> & { timestamp?: number }) => {
      const newPoint = {
        ...point,
        timestamp: point.timestamp ?? Date.now(),
      } as T;

      setData((prev) => {
        const updated = [...prev, newPoint];
        return updated.length > maxPoints ? updated.slice(-maxPoints) : updated;
      });
    },
    [maxPoints]
  );

  const clearData = useCallback(() => {
    setData([]);
  }, []);

  useEffect(() => {
    if (!websocketUrl) return;

    const connect = () => {
      wsRef.current = new WebSocket(websocketUrl);

      wsRef.current.onmessage = (event) => {
        try {
          const point = JSON.parse(event.data);
          addDataPoint(point);
        } catch (e) {
          console.error('Failed to parse WebSocket message:', e);
        }
      };

      wsRef.current.onclose = () => {
        reconnectTimeoutRef.current = setTimeout(connect, 3000);
      };

      wsRef.current.onerror = () => {
        wsRef.current?.close();
      };
    };

    connect();

    return () => {
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
      wsRef.current?.close();
    };
  }, [websocketUrl, addDataPoint]);

  return { data, addDataPoint, clearData };
}
```

